const effects=[
{id:'halo',name:'Golden hour',cat:'Beauty',emoji:'☼',desc:'A warm, sun-kissed glow.',img:'photo-1534528741775-53994a69daeb',tag:'GLOW',color:'#f6d7a8'},
{id:'kitty',name:'Little mischief',cat:'Animals',emoji:'🐱',desc:'A tiny feline transformation.',img:'photo-1524504388940-b1c1722653e1',tag:'PLAYFUL',color:'#e9d5c8'},
{id:'pop',name:'Pop star',cat:'Funny',emoji:'✦',desc:'Main character energy.',img:'photo-1529139574466-a303027c1d8b',tag:'TRENDING',color:'#e6c7ed'},
{id:'bigmouth',name:'Big mood',cat:'Distortion',emoji:'😮',desc:'Go big. Go ridiculous.',img:'photo-1506794778202-cad84cf45f1d',tag:'DISTORT',color:'#f3c7bf'},
{id:'lavender',name:'Lavender dream',cat:'Beauty',emoji:'✿',desc:'Soft color, softer mood.',img:'photo-1531123897727-8f129e1688ce',tag:'SOFT',color:'#ddd3f7'},
{id:'alien',name:'Cosmic visitor',cat:'3D',emoji:'👽',desc:'A little out of this world.',img:'photo-1500648767791-00dcc994a43e',tag:'FANTASY',color:'#c9e6bd'},
{id:'tiny',name:'Tiny head energy',cat:'Distortion',emoji:'🤏',desc:'A playful head proportion warp.',img:'photo-1508214751196-bcfd4ca60f91',tag:'SILLY',color:'#e9d9bf'},
{id:'butterfly',name:'Butterfly effect',cat:'3D',emoji:'🦋',desc:'A little magic around your face.',img:'photo-1526510747491-58f928ec870f',tag:'MAGIC',color:'#d4dafa'}];
const pages=['explore','signin','signup','recovery','studio','effects','capture','creations','creator','profile'];let activeEffect=null,stream=null,mediaBlob=null,recording=false,recorder=null,recordedChunks=[],cameraFacing='user',currentMode='photo',toastTimer;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function navigate(page){if(!pages.includes(page))page='explore';$$('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+page));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').textContent=page==='explore'?'Explore':page==='studio'?'Camera studio':page.charAt(0).toUpperCase()+page.slice(1);$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});if(page!=='studio'&&stream){stopCamera()}if(page==='studio')renderStudioEffects();if(page==='effects')renderLibrary();if(page==='explore')renderHome()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){e.preventDefault();navigate(b.dataset.page)}});
function card(e){return `<article class="filter-card" data-id="${e.id}" data-cat="${e.cat}"><div class="filter-thumb" style="background:${e.color}"><img loading="lazy" src="https://images.unsplash.com/${e.img}?w=500&auto=format&fit=crop&q=75" alt="${e.name}"><span class="filter-emoji">${e.emoji}</span><span class="filter-play">TRY THIS EFFECT ↗</span></div><div class="filter-meta"><div><b>${e.name}</b><small>${e.cat} · IRIS original</small></div><button class="heart" aria-label="Favorite">♡</button></div></article>`}
function renderHome(cat='All'){const list=effects.filter(e=>cat==='All'||e.cat===cat);$('#homeFilters').innerHTML=list.slice(0,4).map(card).join('')}
function renderLibraryFiltered(cat='All',q=''){const list=effects.filter(e=>(cat==='All'||e.cat===cat)&&(e.name+' '+e.desc).toLowerCase().includes(q.toLowerCase()));$('#libraryFilters').innerHTML=list.length?list.map(card).join(''):'<p class="muted">No effects found. Try another search.</p>'}
function renderStudioEffects(cat='All',q=''){const list=effects.filter(e=>(cat==='All'||e.cat===cat)&&(e.name+' '+e.desc).toLowerCase().includes(q.toLowerCase()));$('#studioFilters').innerHTML=list.map(e=>`<button class="studio-effect ${activeEffect?.id===e.id?'selected':''}" data-effect="${e.id}"><span class="studio-effect-thumb" style="background:${e.color}">${e.emoji}</span><span><b>${e.name}</b><small>${e.desc}</small></span></button>`).join('')}
function renderStudioEffectsDefault(){renderStudioEffects()}
function renderHomeDefault(){renderHome()}
function renderLibrary(){const active=$('.library-tabs .active')?.dataset.library||'All';renderLibraryFiltered(active,$('#librarySearch')?.value||'')}
function chooseEffect(id){activeEffect=effects.find(e=>e.id===id)||null;$('#selectedEmoji').textContent=activeEffect?.emoji||'✳';$('#selectedName').textContent=activeEffect?.name||'No filter selected';$('#selectedDescription').textContent=activeEffect?.desc||'Choose an effect to try it';renderStudioEffects($('.effect-tabs .active')?.dataset.effectCat||'All',$('#effectSearch').value);drawOverlay()}
function drawOverlay(){const c=$('#filterCanvas'),frame=$('#cameraFrame');if(!c||!frame)return;const w=frame.clientWidth,h=frame.clientHeight;c.width=w*devicePixelRatio;c.height=h*devicePixelRatio;const x=c.getContext('2d');x.scale(devicePixelRatio,devicePixelRatio);if(!activeEffect)return;x.textAlign='center';x.font='68px sans-serif';let label=activeEffect.emoji;x.shadowColor='#0008';x.shadowBlur=12;if(activeEffect.cat==='Distortion'){x.font='bold 19px sans-serif';x.fillStyle='#fff';x.fillText(activeEffect.id==='bigmouth'?'BIG MOOD 😮':activeEffect.id==='tiny'?'TINY HEAD ENERGY 🤏':'SQUISH MODE',w/2,h*.78)}else{x.fillText(label,w/2,h*.34)}}
async function enableCamera(){try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:cameraFacing,width:{ideal:1280},height:{ideal:720}},audio:true});const v=$('#cameraVideo');v.srcObject=stream;v.classList.add('ready');$('#cameraPlaceholder').style.display='none';$('#faceGuide').style.display='block';toast('Camera is on. Pick an effect and have fun!')}catch(err){toast(err.name==='NotAllowedError'?'Camera permission was denied. You can enable it in browser settings.':'Could not access the camera on this device.');}}
function stopCamera(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}const v=$('#cameraVideo');if(v){v.srcObject=null;v.classList.remove('ready')}if($('#cameraPlaceholder'))$('#cameraPlaceholder').style.display='block';if($('#faceGuide'))$('#faceGuide').style.display='none';if(recorder&&recorder.state==='recording')recorder.stop()}
function capture(){if(!stream){toast('Enable your camera first.');return}const v=$('#cameraVideo');if(currentMode==='photo'){const c=document.createElement('canvas');c.width=v.videoWidth||720;c.height=v.videoHeight||1280;const ctx=c.getContext('2d');if($('#mirrorBtn').textContent.includes('on')){ctx.translate(c.width,0);ctx.scale(-1,1)}ctx.drawImage(v,0,0,c.width,c.height);if(activeEffect){ctx.font='90px sans-serif';ctx.textAlign='center';ctx.fillText(activeEffect.emoji,c.width/2,c.height*.34)}c.toBlob(blob=>{mediaBlob=blob;showCapture(URL.createObjectURL(blob),'image')},'image/jpeg',.92)}else{if(!recording){recordedChunks=[];try{recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)recordedChunks.push(e.data)};recorder.onstop=()=>{mediaBlob=new Blob(recordedChunks,{type:recorder.mimeType||'video/webm'});showCapture(URL.createObjectURL(mediaBlob),'video')};recorder.start();recording=true;$('#captureBtn').classList.add('recording');toast('Recording… tap the button to finish.')}catch(e){toast('Video recording is not supported in this browser.')}}else{recorder.stop();recording=false;$('#captureBtn').classList.remove('recording')}}}
function showCapture(url,type){navigate('capture');const box=$('#resultMedia');box.innerHTML=type==='image'?'<img src="'+url+'" alt="Your IRIS creation">':'<video src="'+url+'" controls autoplay loop></video>'}
function download(){if(!mediaBlob){toast('Capture a photo or video first.');return}const a=document.createElement('a');a.href=URL.createObjectURL(mediaBlob);a.download='iris-creation.'+(mediaBlob.type.includes('video')?'webm':'jpg');a.click();toast('Your creation is downloading.')}
function init(){renderHome();renderLibrary('All');renderStudioEffects();document.addEventListener('click',e=>{const c=e.target.closest('.filter-card');if(c){navigate('studio');chooseEffect(c.dataset.id)}const ef=e.target.closest('[data-effect]');if(ef)chooseEffect(ef.dataset.effect);const heart=e.target.closest('.heart');if(heart){heart.textContent=heart.textContent==='♡'?'♥':'♡';heart.style.color=heart.textContent==='♥'?'#f27e70':''}});$$('.category').forEach(b=>b.addEventListener('click',()=>{$$('.category').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderHome(b.dataset.filter)}));$$('.library-tabs button').forEach(b=>b.addEventListener('click',()=>{$$('.library-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderLibrary(b.dataset.library,$('#librarySearch').value)}));$('#librarySearch').addEventListener('input',renderLibrary);$$('.effect-tabs button').forEach(b=>b.addEventListener('click',()=>{$$('.effect-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderStudioEffects(b.dataset.effectCat,$('#effectSearch').value)}));$('#effectSearch').addEventListener('input',()=>renderStudioEffects($('.effect-tabs .active').dataset.effectCat,$('#effectSearch').value));$('#enableCamera').addEventListener('click',enableCamera);$('#captureBtn').addEventListener('click',capture);$('#downloadBtn').addEventListener('click',download);$('#saveCreation').addEventListener('click',download);$('#shareCreation').addEventListener('click',async()=>{if(!mediaBlob){toast('Capture something first.');return}try{const file=new File([mediaBlob],'iris-creation.jpg',{type:mediaBlob.type});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'My IRIS creation',text:'See beyond yourself.'})}else{await navigator.clipboard.writeText(location.href);toast('Page link copied. Download your creation to share it!')}}catch(e){toast('Sharing was cancelled.')}});$('#clearFilter').addEventListener('click',()=>chooseEffect(null));$('#intensitySlider').addEventListener('input',e=>$('#intensityValue').textContent=e.target.value+'%');$('#mirrorBtn').addEventListener('click',e=>{e.currentTarget.textContent=e.currentTarget.textContent.includes('on')?'⇋ Mirror off':'⇋ Mirror on';$('#cameraVideo').style.transform=e.currentTarget.textContent.includes('on')?'scaleX(-1)':''});$('#flipCamera').addEventListener('click',async()=>{if(!stream){toast('Enable the camera first.');return}cameraFacing=cameraFacing==='user'?'environment':'user';stopCamera();await enableCamera()});$('#closeCamera').addEventListener('click',()=>{stopCamera();toast('Camera turned off.')});$$('.mode-switch button').forEach(b=>b.addEventListener('click',()=>{$$('.mode-switch button').forEach(x=>x.classList.remove('active'));b.classList.add('active');currentMode=b.dataset.mode;$('#captureBtn').classList.remove('recording')}));$('#menuBtn').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$$('.demo-form').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();toast('This is a frontend prototype — authentication will be connected later.')}));$('.show-pass')?.addEventListener('click',e=>{const i=e.currentTarget.previousElementSibling;i.type=i.type==='password'?'text':'password';e.currentTarget.textContent=i.type==='password'?'Show':'Hide'});$('#saveFilter').addEventListener('click',()=>toast('Draft preview saved locally for this demo.'));window.addEventListener('resize',drawOverlay)}
init();